function ConnectedApp() {
  const [session, setSession] = useState(null); const [account, setAccount] = useState(null); const [selectedTripId,setSelectedTripId]=useState(()=>localStorage.getItem("tripmate-active-trip")||""); const [createOpen,setCreateOpen]=useState(false); const [loading, setLoading] = useState(true); const [error, setError] = useState("");const [pendingJoinTripId,setPendingJoinTripId]=useState("");const [pendingJoinStatus,setPendingJoinStatus]=useState("pending");
  const [inviteToken,setInviteToken]=useState(()=>new URLSearchParams(window.location.search).get("invite")||localStorage.getItem("tripmate-pending-invite")||"");
  const [claimingInvite,setClaimingInvite]=useState(Boolean(inviteToken));
  const refresh = async () => {
    try { const context = await getMyTripContext(); setAccount(context); setError(""); }
    catch (err) { setError(err.message || "โหลดข้อมูลไม่สำเร็จ"); }
  };
  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => { setSession(data.session); setLoading(false); });
    const { data: listener } = supabase.auth.onAuthStateChange((_event, next) => { setSession(next); if (!next) setAccount(null); });
    return () => listener.subscription.unsubscribe();
  }, []);
  useEffect(() => { if (session) refresh(); }, [session?.user?.id]);
  useEffect(()=>{if(inviteToken)localStorage.setItem("tripmate-pending-invite",inviteToken);},[inviteToken]);
  useEffect(()=>{if(account?.trips?.length&&!account.trips.some((item)=>item.id===selectedTripId))setSelectedTripId(account.trips[0].id);},[account?.trips,selectedTripId]);
  useEffect(() => {
    if (!session || !inviteToken || !account) return;
    let cancelled=false;setClaimingInvite(true);
    claimInvite(inviteToken).then(async(result)=>{if(cancelled)return;const tripId=result?.trip_id;if(result?.status==="approved"){localStorage.removeItem("tripmate-pending-invite");window.history.replaceState({},"",window.location.pathname);setInviteToken("");setPendingJoinTripId("");setSelectedTripId(tripId);localStorage.setItem("tripmate-active-trip",tripId);await refresh();}else{setPendingJoinTripId(tripId||"");setPendingJoinStatus(result?.status||"pending");}}).catch((err)=>{if(cancelled)return;setError(err.message||"ลิงก์เชิญไม่ถูกต้องหรือหมดอายุ");}).finally(()=>{if(!cancelled)setClaimingInvite(false);});
    return()=>{cancelled=true;};
  }, [session?.user?.id, inviteToken, Boolean(account)]);
  useEffect(()=>{if(!session||!account||!inviteToken||!pendingJoinTripId)return;const timer=window.setInterval(()=>getInviteStatus(inviteToken).then(async(result)=>{setPendingJoinStatus(result?.status||"pending");if(result?.status!=="approved")return;const tripId=result.trip_id;localStorage.removeItem("tripmate-pending-invite");window.history.replaceState({},"",window.location.pathname);setInviteToken("");setPendingJoinTripId("");setSelectedTripId(tripId);localStorage.setItem("tripmate-active-trip",tripId);await refresh();}).catch(()=>{}),4000);return()=>window.clearInterval(timer);},[session?.user?.id,Boolean(account),inviteToken,pendingJoinTripId]);
  if (loading || (session && (!account||claimingInvite))) return <ThemeProvider theme={theme}><LoadingScreen/></ThemeProvider>;
  if (!session) return <AuthScreen inviteToken={inviteToken}/>;
  if (error) return <ThemeProvider theme={theme}><Box className="auth-shell"><Alert severity="error">{error}</Alert></Box></ThemeProvider>;
  if (!account.trips.length&&pendingJoinTripId)return <><JoinPendingScreen status={pendingJoinStatus} onRetry={()=>claimInvite(inviteToken).then((result)=>setPendingJoinStatus(result?.status||"pending")).catch((err)=>setError(err.message))} onCreate={()=>setCreateOpen(true)} onLogout={()=>supabase.auth.signOut()}/><CreateTripDialog open={createOpen} onClose={()=>setCreateOpen(false)} user={session.user} onCreated={async(id)=>{await refresh();setSelectedTripId(id);localStorage.setItem("tripmate-active-trip",id);setCreateOpen(false);}}/></>;
  if (!account.trips.length) return <CreateTripScreen user={session.user} onCreated={refresh}/>;
  const active=chooseTrip(account.trips,selectedTripId);
  const selectTrip=(id)=>{setSelectedTripId(id);localStorage.setItem("tripmate-active-trip",id);};
  return <><App account={account} trip={active} trips={account.trips} onTripChange={selectTrip} onNewTrip={()=>setCreateOpen(true)} onRefresh={refresh}/><CreateTripDialog open={createOpen} onClose={()=>setCreateOpen(false)} user={session.user} onCreated={async(id)=>{await refresh();selectTrip(id);}}/></>;
}

const appRoot = window.__tripMateRoot || (window.__tripMateRoot = createRoot(document.getElementById("root")));
const previewDemo = import.meta.env.DEV && new URLSearchParams(window.location.search).has("demo");
appRoot.render(<React.StrictMode>{isSupabaseConfigured && !previewDemo ? <ConnectedApp/> : <App/>}</React.StrictMode>);
if("serviceWorker" in navigator&&import.meta.env.PROD)window.addEventListener("load",()=>navigator.serviceWorker.register("/sw.js").catch(()=>{}));
